for name in ['007', '008', '009']:
    im = Image.open(f'/home/robot/captures/wrist_right_{name}.jpg')
    # Find blue pixels (R < 50, G < 50, B > 100)
    w, h = im.size
    blue_pixels = []
    for y in range(h):
        for x in range(w):
            r, g, b = im.getpixel((x, y))
            if b > 100 and r < 80 and g < 80:
                blue_pixels.append((x, y))
    if blue_pixels:
        xs = [p[0] for p in blue_pixels]
        ys = [p[1] for p in blue_pixels]
